sourcesContent:
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { FaUser, FaEnvelope, FaCalendar, FaTrophy, FaFire, FaClock, FaSignOutAlt, FaCamera, FaHeart, FaTrash, FaMars, FaVenus, FaUpload, FaImage, FaEdit, FaSave, FaTimes, FaWeight, FaRuler, FaBirthdayCake, FaBrain, FaMoon, FaApple, FaRunning, FaCoffee, FaSave as FaSaveAll } from 'react-icons/fa';

function Profile() {
  const navigate = useNavigate();
  const [isEditing, setIsEditing] = useState(false);
  const [showAvatarPicker, setShowAvatarPicker] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [customImageUrl, setCustomImageUrl] = useState('');
  const [showUrlInput, setShowUrlInput] = useState(false);
  
  // User Information State
  const [userInfo, setUserInfo] = useState({
    // Basic Info
    name: '',
    email: '',
    age: '',
    birthday: '',
    gender: '',
    
    // Physical Info
    height: '',
    weight: '',
    
    // Mental Health Info
    primaryConcern: '',
    sleepHours: '',
    exerciseFrequency: '',
    stressLevel: '',
    moodPattern: '',
    therapyHistory: '',
    medications: '',
    
    // Lifestyle
    dailyRoutine: '',
    waterIntake: '',
    caffeineIntake: '',
    socialTime: '',
    
    // Goals
    mentalHealthGoals: '',
    
    // Metadata
    joined: '',
    avatar: null,
    avatarCategory: null
  });

  const [tempInfo, setTempInfo] = useState({});

  // Avatar arrays
  const boyAvatars = [
    { id: 1, url: 'https://randomuser.me/api/portraits/men/1.jpg', name: 'Alex' },
    { id: 2, url: 'https://randomuser.me/api/portraits/men/2.jpg', name: 'Ben' },
    { id: 3, url: 'https://randomuser.me/api/portraits/men/3.jpg', name: 'Charlie' },
    { id: 4, url: 'https://randomuser.me/api/portraits/men/4.jpg', name: 'David' },
    { id: 5, url: 'https://randomuser.me/api/portraits/men/5.jpg', name: 'Ethan' },
    { id: 6, url: 'https://randomuser.me/api/portraits/men/6.jpg', name: 'Frank' },
  ];

  const girlAvatars = [
    { id: 1, url: 'https://randomuser.me/api/portraits/women/1.jpg', name: 'Emma' },
    { id: 2, url: 'https://randomuser.me/api/portraits/women/2.jpg', name: 'Sophia' },
    { id: 3, url: 'https://randomuser.me/api/portraits/women/3.jpg', name: 'Olivia' },
    { id: 4, url: 'https://randomuser.me/api/portraits/women/4.jpg', name: 'Ava' },
    { id: 5, url: 'https://randomuser.me/api/portraits/women/5.jpg', name: 'Mia' },
    { id: 6, url: 'https://randomuser.me/api/portraits/women/6.jpg', name: 'Isabella' },
  ];

  const customAvatars = [
    { id: 1, url: 'https://i.pinimg.com/736x/a1/27/73/a1277303ec49ee936b2ba11bb3a98a18.jpg', name: 'Cartoon 1', category: 'cartoon' },
    { id: 2, url: 'https://i1-c.pinimg.com/1200x/67/ef/9d/67ef9d9bb1b009281379840a737c811f.jpg', name: 'Cartoon 2', category: 'cartoon' },
  ];

  // Mental health options
  const concerns = [
    'Anxiety', 'Depression', 'Stress Management', 'Sleep Issues', 
    'Self-esteem', 'Relationship Issues', 'Work-Life Balance', 'Burnout'
  ];
  
  const stressLevels = ['Low', 'Mild', 'Moderate', 'High', 'Very High'];
  const exerciseOptions = ['Daily', '3-5 times/week', '1-2 times/week', 'Rarely', 'Never'];
  const moodPatterns = ['Morning Person', 'Night Owl', 'Irregular', 'Consistent'];

  useEffect(() => {
    // Load saved data
    const savedAvatar = localStorage.getItem('userAvatar');
    const savedCategory = localStorage.getItem('userAvatarCategory');
    const savedUserInfo = localStorage.getItem('userInfo');
    
    const defaultInfo = {
      name: localStorage.getItem('userName') || 'User',
      email: localStorage.getItem('userEmail') || 'user@example.com',
      joined: new Date().toLocaleDateString(),
      avatar: savedAvatar,
      avatarCategory: savedCategory,
      age: '',
      birthday: '',
      gender: '',
      height: '',
      weight: '',
      primaryConcern: '',
      sleepHours: '',
      exerciseFrequency: '',
      stressLevel: '',
      moodPattern: '',
      therapyHistory: '',
      medications: '',
      dailyRoutine: '',
      waterIntake: '',
      caffeineIntake: '',
      socialTime: '',
      mentalHealthGoals: ''
    };
    
    if (savedUserInfo) {
      setUserInfo({ ...defaultInfo, ...JSON.parse(savedUserInfo) });
    } else {
      setUserInfo(defaultInfo);
    }
    setTempInfo({ ...defaultInfo, ...(savedUserInfo ? JSON.parse(savedUserInfo) : defaultInfo) });
  }, []);

  const stats = [
    { icon: <FaFire color="#e74c3c" />, value: '12', label: 'Day Streak' },
    { icon: <FaTrophy color="#f39c12" />, value: '8', label: 'Badges Earned' },
    { icon: <FaClock color="#3498db" />, value: '245', label: 'Focus Minutes' },
    { icon: <FaHeart color="#e84393" />, value: '156', label: 'Moods Logged' },
  ];

  const handleEdit = () => {
    setTempInfo({ ...userInfo });
    setIsEditing(true);
  };

  const handleSave = () => {
    setUserInfo({ ...tempInfo });
    localStorage.setItem('userInfo', JSON.stringify(tempInfo));
    localStorage.setItem('userName', tempInfo.name);
    setIsEditing(false);
  };

  const handleCancel = () => {
    setTempInfo({ ...userInfo });
    setIsEditing(false);
  };

  const handleChange = (field, value) => {
    setTempInfo({ ...tempInfo, [field]: value });
  };

  // Avatar handlers
  const handleUrlSubmit = () => {
    if (customImageUrl.trim()) {
      setUserInfo({ ...userInfo, avatar: customImageUrl, avatarCategory: 'custom' });
      localStorage.setItem('userAvatar', customImageUrl);
      localStorage.setItem('userAvatarCategory', 'custom');
      setShowAvatarPicker(false);
      setCustomImageUrl('');
      setShowUrlInput(false);
    }
  };

  const handleImageUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imageData = reader.result;
        setUserInfo({ ...userInfo, avatar: imageData, avatarCategory: 'uploaded' });
        localStorage.setItem('userAvatar', imageData);
        localStorage.setItem('userAvatarCategory', 'uploaded');
        setShowAvatarPicker(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAvatarSelect = (avatarUrl, category) => {
    setUserInfo({ ...userInfo, avatar: avatarUrl, avatarCategory: category });
    localStorage.setItem('userAvatar', avatarUrl);
    localStorage.setItem('userAvatarCategory', category);
    setShowAvatarPicker(false);
    setSelectedCategory(null);
  };

  const handleLogout = () => {
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userName');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userAvatar');
    localStorage.removeItem('userAvatarCategory');
    localStorage.removeItem('userInfo');
    navigate('/');
  };

  const renderField = (label, field, type = 'text', options = null) => {
    const value = isEditing ? tempInfo[field] : userInfo[field];
    
    if (isEditing) {
      if (options) {
        return (
          <select
            value={value || ''}
            onChange={(e) => handleChange(field, e.target.value)}
            style={styles.select}
          >
            <option value="">Select {label}</option>
            {options.map(opt => (
              <option key={opt} value={opt}>{opt}</option>
            ))}
          </select>
        );
      }
      return (
        <input
          type={type}
          value={value || ''}
          onChange={(e) => handleChange(field, e.target.value)}
          placeholder={`Enter ${label}`}
          style={styles.input}
        />
      );
    }
    
    return <p style={styles.fieldValue}>{value || 'Not provided'}</p>;
  };

  const currentInfo = isEditing ? tempInfo : userInfo;

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>👤 Profile</h1>
          <p style={styles.subtitle}>Manage your account and health information</p>
          {!isEditing ? (
            <button onClick={handleEdit} style={styles.editProfileBtn}>
              <FaEdit /> Edit Profile
            </button>
          ) : (
            <div style={styles.editActions}>
              <button onClick={handleSave} style={styles.saveProfileBtn}>
                <FaSaveAll /> Save All
              </button>
              <button onClick={handleCancel} style={styles.cancelProfileBtn}>
                <FaTimes /> Cancel
              </button>
            </div>
          )}
        </div>

        {/* Avatar Card */}
        <div style={styles.avatarCard}>
          <div style={styles.avatarContainer}>
            <div style={styles.avatarWrapper}>
              {currentInfo.avatar ? (
                <img src={currentInfo.avatar} alt="Avatar" style={styles.avatarImage} />
              ) : (
                <div style={styles.avatarPlaceholder}>
                  <FaUser size={50} color="#ccc" />
                </div>
              )}
              <button 
                style={styles.editAvatarBtn}
                onClick={() => setShowAvatarPicker(!showAvatarPicker)}
              >
                <FaCamera size={16} />
              </button>
            </div>
            <h2 style={styles.userName}>{currentInfo.name}</h2>
            <div style={styles.userInfo}>
              <div style={styles.infoRow}><FaEnvelope /> {currentInfo.email}</div>
              <div style={styles.infoRow}><FaCalendar /> Member since {currentInfo.joined}</div>
            </div>
          </div>

          {/* Avatar Picker Popup - Same as before */}
          {showAvatarPicker && (
            <div style={styles.avatarPicker}>
              <div style={styles.pickerHeader}>
                <h4>Choose Your Avatar</h4>
                <button onClick={() => setShowAvatarPicker(false)} style={styles.closeBtn}>✕</button>
              </div>
              <div style={styles.uploadSection}>
                <label style={styles.uploadBtn}>
                  <FaUpload /> Upload Photo
                  <input type="file" accept="image/*" onChange={handleImageUpload} style={{ display: 'none' }} />
                </label>
                <button style={styles.urlBtn} onClick={() => setShowUrlInput(!showUrlInput)}>
                  <FaImage /> Use Image URL
                </button>
              </div>
              {showUrlInput && (
                <div style={styles.urlInputContainer}>
                  <input type="text" placeholder="Paste image URL here..." value={customImageUrl} onChange={(e) => setCustomImageUrl(e.target.value)} style={styles.urlInput} />
                  <button onClick={handleUrlSubmit} style={styles.urlSubmitBtn}>Add</button>
                </div>
              )}
              {!selectedCategory ? (
                <>
                  <div style={styles.categoryGrid}>
                    <div style={styles.categoryCard} onClick={() => setSelectedCategory('boys')}>
                      <div style={styles.categoryIcon}><FaMars size={40} color="#3498db" /></div>
                      <h4>Boys</h4>
                    </div>
                    <div style={styles.categoryCard} onClick={() => setSelectedCategory('girls')}>
                      <div style={styles.categoryIcon}><FaVenus size={40} color="#e84393" /></div>
                      <h4>Girls</h4>
                    </div>
                  </div>
                  <div style={styles.customSection}>
                    <h4 style={styles.customTitle}>🎨 More Avatars</h4>
                    <div style={styles.avatarGrid}>
                      {customAvatars.map((avatar) => (
                        <div key={avatar.id} style={styles.avatarOption} onClick={() => handleAvatarSelect(avatar.url, avatar.category)}>
                          <img src={avatar.url} alt={avatar.name} style={styles.avatarOptionImage} />
                        </div>
                      ))}
                    </div>
                  </div>
                </>
              ) : (
                <>
                  <button onClick={() => setSelectedCategory(null)} style={styles.backBtn}>← Back</button>
                  <div style={styles.avatarGrid}>
                    {(selectedCategory === 'boys' ? boyAvatars : girlAvatars).map((avatar) => (
                      <div key={avatar.id} style={styles.avatarOption} onClick={() => handleAvatarSelect(avatar.url, selectedCategory)}>
                        <img src={avatar.url} alt={avatar.name} style={styles.avatarOptionImage} />
                      </div>
                    ))}
                  </div>
                </>
              )}
              {currentInfo.avatar && (
                <button onClick={() => {
                  setUserInfo({ ...currentInfo, avatar: null, avatarCategory: null });
                  localStorage.removeItem('userAvatar');
                  localStorage.removeItem('userAvatarCategory');
                  setShowAvatarPicker(false);
                }} style={styles.removeBtn}>
                  <FaTrash /> Remove Avatar
                </button>
              )}
            </div>
          )}
        </div>

        {/* Personal Information Section */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}><FaUser /> Personal Information</h3>
          <div style={styles.formGrid}>
            <div style={styles.formField}>
              <label style={styles.label}>Full Name</label>
              {renderField('Full Name', 'name')}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}>Age</label>
              {renderField('Age', 'age', 'number')}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}><FaBirthdayCake /> Birthday</label>
              {renderField('Birthday', 'birthday', 'date')}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}>Gender</label>
              {isEditing ? (
                <select value={tempInfo.gender || ''} onChange={(e) => handleChange('gender', e.target.value)} style={styles.select}>
                  <option value="">Select Gender</option>
                  <option value="Male">Male</option>
                  <option value="Female">Female</option>
                  <option value="Non-binary">Non-binary</option>
                  <option value="Prefer not to say">Prefer not to say</option>
                </select>
              ) : (
                <p style={styles.fieldValue}>{currentInfo.gender || 'Not provided'}</p>
              )}
            </div>
          </div>
        </div>

        {/* Physical Information */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}><FaRuler /> Physical Information</h3>
          <div style={styles.formGrid}>
            <div style={styles.formField}>
              <label style={styles.label}><FaRuler /> Height (cm)</label>
              {renderField('Height', 'height', 'number')}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}><FaWeight /> Weight (kg)</label>
              {renderField('Weight', 'weight', 'number')}
            </div>
          </div>
        </div>

        {/* Mental Health Information */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}><FaBrain /> Mental Health Information</h3>
          <div style={styles.formGrid}>
            <div style={styles.formField}>
              <label style={styles.label}>Primary Concern</label>
              {renderField('Primary Concern', 'primaryConcern', 'text', concerns)}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}><FaMoon /> Average Sleep (hours/night)</label>
              {renderField('Sleep Hours', 'sleepHours', 'number')}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}><FaRunning /> Exercise Frequency</label>
              {renderField('Exercise Frequency', 'exerciseFrequency', 'text', exerciseOptions)}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}>Stress Level</label>
              {renderField('Stress Level', 'stressLevel', 'text', stressLevels)}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}>Mood Pattern</label>
              {renderField('Mood Pattern', 'moodPattern', 'text', moodPatterns)}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}>Therapy History</label>
              {isEditing ? (
                <textarea value={tempInfo.therapyHistory || ''} onChange={(e) => handleChange('therapyHistory', e.target.value)} placeholder="e.g., Currently in therapy, Past therapy, etc." style={styles.textarea} rows="2" />
              ) : (
                <p style={styles.fieldValue}>{currentInfo.therapyHistory || 'Not provided'}</p>
              )}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}>Current Medications</label>
              {isEditing ? (
                <textarea value={tempInfo.medications || ''} onChange={(e) => handleChange('medications', e.target.value)} placeholder="List any medications (optional)" style={styles.textarea} rows="2" />
              ) : (
                <p style={styles.fieldValue}>{currentInfo.medications || 'Not provided'}</p>
              )}
            </div>
          </div>
        </div>

        {/* Lifestyle Information */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}><FaCoffee /> Lifestyle Information</h3>
          <div style={styles.formGrid}>
            <div style={styles.formField}>
              <label style={styles.label}>Daily Routine</label>
              {isEditing ? (
                <textarea value={tempInfo.dailyRoutine || ''} onChange={(e) => handleChange('dailyRoutine', e.target.value)} placeholder="Describe your typical day" style={styles.textarea} rows="2" />
              ) : (
                <p style={styles.fieldValue}>{currentInfo.dailyRoutine || 'Not provided'}</p>
              )}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}><FaApple /> Water Intake (glasses/day)</label>
              {renderField('Water Intake', 'waterIntake', 'number')}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}><FaCoffee /> Caffeine Intake</label>
              {isEditing ? (
                <input type="text" value={tempInfo.caffeineIntake || ''} onChange={(e) => handleChange('caffeineIntake', e.target.value)} placeholder="e.g., 2 cups coffee" style={styles.input} />
              ) : (
                <p style={styles.fieldValue}>{currentInfo.caffeineIntake || 'Not provided'}</p>
              )}
            </div>
            <div style={styles.formField}>
              <label style={styles.label}>Social Time (hours/week)</label>
              {renderField('Social Time', 'socialTime', 'number')}
            </div>
          </div>
        </div>

        {/* Goals Section */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>🎯 Mental Health Goals</h3>
          <div style={styles.formField}>
            <label style={styles.label}>What are your mental health goals?</label>
            {isEditing ? (
              <textarea value={tempInfo.mentalHealthGoals || ''} onChange={(e) => handleChange('mentalHealthGoals', e.target.value)} placeholder="e.g., Reduce anxiety, Improve sleep, Build confidence" style={styles.textarea} rows="3" />
            ) : (
              <p style={styles.fieldValue}>{currentInfo.mentalHealthGoals || 'Not provided'}</p>
            )}
          </div>
        </div>

        {/* Stats Grid */}
        <div style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <div key={index} style={styles.statCard}>
              <div style={styles.statIcon}>{stat.icon}</div>
              <div style={styles.statValue}>{stat.value}</div>
              <div style={styles.statLabel}>{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Logout Button */}
        <div style={styles.menuCard}>
          <button onClick={handleLogout} style={styles.logoutBtn}>
            <FaSignOutAlt /> Logout
          </button>
        </div>
      </div>
    </div>
  );
}

